#[path="../handheld/src/lab_control_line.rs"]mod lab_control_line;
use lab_control_line::*;
fn events(p:&mut Parser,line:&[u8],at:u64)->Vec<Event>{line.iter().map(|&b|p.feed(b,at)).collect()}
fn complete(e:&[Event])->Vec<Result<Request,Error>>{e.iter().filter_map(|e|if let Event::Complete(r)=e{Some(*r)}else{None}).collect()}
#[test]fn exact_actions_nonce_and_crlf(){for(command,action)in [("PING",Action::Ping),("REBOOT",Action::Reboot),("DFU",Action::Dfu),("HOST33",Action::Host33),("HOST47",Action::Host47)]{for end in ["\n","\r\n"]{let mut p=Parser::new();let e=events(&mut p,format!("!MBLAB1 0123456789aBcDeF {command}{end}").as_bytes(),10);assert!(!e.contains(&Event::Pass));assert_eq!(complete(&e),vec![Ok(Request{nonce:0x0123456789abcdef,action})]);assert_eq!(p.feed(b'W',11),Event::Pass);}}}
#[test]fn no_actions_before_lf(){let mut p=Parser::new();let e=events(&mut p,b"!MBLAB1 ffffffffffffffff REBOOT",0);assert!(e.iter().all(|e|*e==Event::Consumed));assert_eq!(p.tick(1999),Event::Consumed);assert_eq!(p.feed(b'\n',1999),Event::Complete(Ok(Request{nonce:u64::MAX,action:Action::Reboot})));}
#[test]fn malformed_lines_never_leak_legacy_keys(){for s in ["!W~@^$I\n","!MBLAB1 000000000000000g PING\n","!MBLAB1 000000000000000 PING\n","!MBLAB1 00000000000000000 PING\n","!MBLAB1 0000000000000000  PING\n","!MBLAB1 0000000000000000 PING \n","!MBLAB1 0000000000000000 ping\n","!MBLAB1 0000000000000000 PING\rX\n","!MBLAB1 0000000000000000 REBOOT\r\r\n","!MBLAB1 0000000000000000 PING\0\n","!!MBLAB1 0000000000000000 DFU\n"]{let mut p=Parser::new();let e=events(&mut p,s.as_bytes(),0);assert!(!e.contains(&Event::Pass),"{s:?}");let r=complete(&e);assert_eq!(r.len(),1,"{s:?}");assert!(r[0].is_err(),"{s:?}");assert_eq!(p.feed(b'W',1),Event::Pass);}}
#[test]fn overflow_discards_through_lf_then_resynchronizes(){let mut p=Parser::new();assert_eq!(p.feed(b'!',0),Event::Consumed);for _ in 1..MAX_LINE_BYTES{assert_eq!(p.feed(b'W',1),Event::Consumed)}assert_eq!(p.feed(b'I',1),Event::Complete(Err(Error::Overflow)));let tail=events(&mut p,b"~@^$!MBLAB1 0000000000000000 REBOOT\n",2);assert!(tail.iter().all(|x|*x==Event::Consumed));let e=events(&mut p,b"!MBLAB1 0000000000000000 PING\n",3);assert_eq!(complete(&e),vec![Ok(Request{nonce:0,action:Action::Ping})]);}
#[test]fn timeout_tick_discards_and_never_extends_with_input(){let mut p=Parser::new();events(&mut p,b"!MBLAB1 ",100);events(&mut p,b"0000000000000000 REBOOT",2099);assert_eq!(p.tick(2100),Event::Complete(Err(Error::Timeout)));assert_eq!(p.tick(9999),Event::Consumed);assert!(events(&mut p,b"W!MBLAB1 0000000000000000 DFU\r\n",10000).iter().all(|x|*x==Event::Consumed));assert_eq!(p.feed(b'W',10001),Event::Pass);}
#[test]fn timeout_from_feed_consumes_triggering_key_or_newline(){for trigger in [b'W',b'\n']{let mut p=Parser::new();events(&mut p,b"!MBLAB1 0000000000000000 DFU",0);assert_eq!(p.feed(trigger,2000),Event::Complete(Err(Error::Timeout)));if trigger!=b'\n'{assert_eq!(p.feed(b'W',2001),Event::Consumed);assert_eq!(p.feed(b'\n',2002),Event::Consumed)}assert_eq!(p.feed(b'W',2003),Event::Pass);}}
#[test]fn all_truncation_points_are_inert_until_lf_or_timeout(){let line=b"!MBLAB1 0123456789abcdef REBOOT";for n in 1..=line.len(){let mut p=Parser::new();assert!(events(&mut p,&line[..n],0).iter().all(|e|*e==Event::Consumed));assert_eq!(p.tick(2000),Event::Complete(Err(Error::Timeout)));assert_eq!(p.feed(b'\n',2001),Event::Consumed);assert_eq!(p.feed(b'W',2002),Event::Pass);}}
#[test]fn legacy_bytes_and_back_to_back_frames(){let mut p=Parser::new();for b in b"W~@^$I\n\r"{assert_eq!(p.feed(*b,0),Event::Pass)}let e=events(&mut p,b"!MBLAB1 1111111111111111 PING\n!MBLAB1 2222222222222222 HOST33\n",1);assert_eq!(complete(&e),vec![Ok(Request{nonce:0x1111111111111111,action:Action::Ping}),Ok(Request{nonce:0x2222222222222222,action:Action::Host33})]);}
#[test]fn bounded_state_and_no_clock_wrap_expiry(){assert!(std::mem::size_of::<Parser>()<=96);let mut p=Parser::new();p.feed(b'!',u64::MAX-10);assert_eq!(p.tick(u64::MAX),Event::Consumed);assert_eq!(p.tick(0),Event::Consumed);}
